typedef struct {
    int id;
    int pos;
    char dir;
} Ant;

int cmp_pos(const void *a, const void *b) {
    const Ant *x = (const Ant *)a;
    const Ant *y = (const Ant *)b;
    if (x->pos != y->pos) return x->pos - y->pos;
    return x->id - y->id;
}

int main(void) {
    int n, L;

    /* 
       Assumed input format:
       n L
       d1 p1
       d2 p2
       ...
       dn pn

       where di is 'L' or 'R' (possibly also 'l'/'r').
    */
    if (scanf("%d %d", &n, &L) != 2) return 0;

    Ant *ants = (Ant *)malloc(sizeof(Ant) * n);
    if (!ants) return 0;

    for (int i = 0; i < n; i++) {
        char d;
        int p;
        if (scanf(" %c %d", &d, &p) != 2) {
            free(ants);
            return 0;
        }
        ants[i].id = i + 1;
        ants[i].pos = p;
        ants[i].dir = d;
    }

    qsort(ants, n, sizeof(Ant), cmp_pos);

    int lastTime = -1;
    int leftIndex = 0, rightIndex = n - 1;
    int lastId = -1;
    int tie = 0;

    for (int i = 0; i < n; i++) {
        int t;
        int candidateId;

        if (ants[i].dir == 'L' || ants[i].dir == 'l') {
            t = ants[i].pos;
            candidateId = ants[leftIndex].id;
            leftIndex++;
        } else {
            t = L - ants[i].pos;
            candidateId = ants[rightIndex].id;
            rightIndex--;
        }

        if (t > lastTime) {
            lastTime = t;
            lastId = candidateId;
            tie = 0;
        } else if (t == lastTime) {
            if (candidateId != lastId) tie = 1;
            if (candidateId < lastId) lastId = candidateId;
        }
    }

    printf("%d\n", lastTime);
    if (tie) {
        printf("The last ant will be one of ants %d and another ant.\n", lastId);
    } else {
        printf("%d\n", lastId);
    }

    free(ants);
    return 0;
}

