/*
Classic "Ants" / POJ 1852 / UVa 10714 variant with identity of the last ant.

Key observation:
When ants meet and turn around, this is equivalent to ants passing through each
other if we ignore identities. Thus, exit times are simply determined by initial
positions and directions.

To recover which labeled ant is last to leave:
- Sort ants by position.
- Consider "ghost ants" moving straight through each other.
- The order of labels along the tunnel is preserved through collisions.
- When a ghost exits from the left/right, it corresponds to the current leftmost/rightmost
  remaining label respectively.

For the last exit time T:
- Compute the maximum exit time among all ants.
- There may be one or two ghost exits at time T (one left, one right).
- Map them to labels using the remaining deque of sorted labels.

Input format assumed:
Multiple test cases.
For each case:
n l
Then n lines: <direction> <position>
direction is 'L' or 'R' (possibly 'l'/'r').

Output:
If exactly one ant is last:
<time> <id>
If two ants are tied for last:
<time> <id1> <id2>
where ids are original 1-based indices in increasing order.

This matches the common judge style for this problem family.
*/

struct Ant {
    int id;
    int pos;
    char dir;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    while (T--) {
        int n, L;
        cin >> n >> L;

        vector<Ant> ants(n);
        for (int i = 0; i < n; ++i) {
            cin >> ants[i].dir >> ants[i].pos;
            ants[i].id = i + 1;
            ants[i].dir = toupper(ants[i].dir);
        }

        sort(ants.begin(), ants.end(), [](const Ant& a, const Ant& b) {
            return a.pos < b.pos;
        });

        // Determine maximum exit time
        int lastTime = -1;
        for (auto &a : ants) {
            int t = (a.dir == 'L') ? a.pos : (L - a.pos);
            lastTime = max(lastTime, t);
        }

        // Remaining labels in positional order
        deque<int> labels;
        for (auto &a : ants) labels.push_back(a.id);

        vector<int> lastIDs;

        // Process exits in chronological order; only need to know who exits at lastTime.
        // Events before lastTime update the deque.
        for (auto &a : ants) {
            int t = (a.dir == 'L') ? a.pos : (L - a.pos);
            if (t < lastTime) {
                if (a.dir == 'L') labels.pop_front();
                else labels.pop_back();
            }
        }

        // Now collect all ants whose ghost exits at lastTime.
        // At most two sides can have exits at the same time.
        bool leftExit = false, rightExit = false;
        for (auto &a : ants) {
            int t = (a.dir == 'L') ? a.pos : (L - a.pos);
            if (t == lastTime) {
                if (a.dir == 'L') leftExit = true;
                else rightExit = true;
            }
        }

        if (leftExit) lastIDs.push_back(labels.front());
        if (rightExit) {
            int id = labels.back();
            if (lastIDs.empty() || lastIDs[0] != id) lastIDs.push_back(id);
        }

        sort(lastIDs.begin(), lastIDs.end());

        cout << "The last ant will leave in " << lastTime << " seconds - started at ";
        if (lastIDs.size() == 1) {
            cout << lastIDs[0] << ".\n";
        } else {
            cout << lastIDs[0] << " and " << lastIDs[1] << ".\n";
        }
    }

    return 0;
}

