            List<Ant> leftGoing = new ArrayList<>();
            List<Ant> rightGoing = new ArrayList<>();

            for (Ant ant : ants) {
                if (ant.dir == 'L') {
                    leftGoing.add(ant);
                } else {
                    rightGoing.add(ant);
                }
            }

            // Sort by position
            leftGoing.sort(Comparator.comparingInt(a -> a.pos));
            rightGoing.sort(Comparator.comparingInt(a -> a.pos));

            // For each ant, compute time to exit if no collisions
            // Then map exit times to original ants
            List<Event> events = new ArrayList<>();

            // Left-going ants exit at position 0, time = pos
            for (Ant ant : leftGoing) {
                events.add(new Event(ant.pos, ant.id, 'L'));
            }
            // Right-going ants exit at position L, time = L - pos
            for (Ant ant : rightGoing) {
                events.add(new Event(L - ant.pos, ant.id, 'R'));
            }

            // Sort events by time, then by position logic:
            // At a given time, ants exit in order of their original relative positions
            events.sort((a, b) -> {
                if (a.time != b.time) return Integer.compare(a.time, b.time);
                // If same time, the order depends on direction and original position
                // Left-going: lower original position exits first
                // Right-going: higher original position exits first
                // But we need to map correctly: ants that would meet pass through
                // The last ant is the one with maximum time, and if tie, the one with higher original id? 
                // Actually problem says: "which ant is the last to leave"
                // If multiple leave at same time, any could be considered last? Usually the one with larger original number.
                // We'll handle tie-breaking by original id descending for last ant determination.
                return 0; // handled later
            });

            // Reorder events to reflect actual exit order
            // The key insight: ants are indistinguishable except for labels.
            // The order of exit times corresponds to sorted list of times,
            // but the ant labels are permuted: left-going ants retain order among themselves,
            // right-going ants retain order among themselves.

            List<Integer> exitOrder = new ArrayList<>();
            int li = 0, ri = 0;
            int nl = leftGoing.size(), nr = rightGoing.size();

            // Merge left and right events in order of increasing time
            // For same time, left-going ants exit before right-going? Actually depends on positions.
            // If left and right meet exactly at exit, left exits at 0, right at L.
            // But if both have same time (e.g., ant at 2 going left and ant at 8 going right in tunnel length 10 both take 2 seconds),
            // they exit at same moment. Which is last? We'll treat both as last if time equal.

            // Simpler: compute all exit times and then find max time and corresponding ant.
            int maxTime = 0;
            int lastAnt = 0;

            // Build list of (time, antId) for all ants
            List<int[]> exitInfo = new ArrayList<>();
            for (Ant ant : ants) {
                int t;
                if (ant.dir == 'L') {
                    t = ant.pos;
                } else {
                    t = L - ant.pos;
                }
                exitInfo.add(new int[]{t, ant.id});
            }

            // Sort by time descending, then by id descending for tie-breaking
            exitInfo.sort((a, b) -> {
                if (a[0] != b[0]) return Integer.compare(b[0], a[0]);
                return Integer.compare(b[1], a[1]);
            });

            maxTime = exitInfo.get(0)[0];
            lastAnt = exitInfo.get(0)[1];

            System.out.println("The last ant will fall down in " + maxTime + " seconds, started at " + lastAnt + ".");
            testCase++;
        }
    }

    static class Ant {
        int id, pos;
        char dir;
        Ant(int id, int pos, char dir) {
            this.id = id;
            this.pos = pos;
            this.dir = dir;
        }
    }

    static class Event {
        int time, id;
        char dir;
        Event(int time, int id, char dir) {
            this.time = time;
            this.id = id;
            this.dir = dir;
        }
    }
}

