import java.io.*;
import java.util.*;

/*
 * Ants in a tunnel.
 *
 * Key observation:
 * When two ants meet and reverse direction, this is equivalent to them
 * passing through each other if we only care about occupied positions.
 * To determine which labeled ant is last, labels are transferred at meetings.
 *
 * Thus:
 * 1) Compute each ant's exit time ignoring collisions:
 *      left-moving  -> time = position
 *      right-moving -> time = L - position
 * 2) The maximum of these is the total time until all ants leave.
 * 3) Ants leaving at the same time correspond to one or two boundary exits.
 *    To determine the label(s), sort ants by initial position.
 *    The order of labels along the tunnel is preserved under the "pass through"
 *    interpretation:
 *      - an ant leaving from the left at some event gets the current leftmost label
 *      - an ant leaving from the right gets the current rightmost label
 *
 * Input format handled:
 *   T
 *   n l
 *   D p name
 *   ...
 *
 * Direction may be 'L'/'R' or similar strings starting with 'L'/'R'.
 *
 * Output:
 *   If one last ant:
 *     The last ant will leave the tunnel in X seconds - NAME.
 *   If two ants can be considered last simultaneously:
 *     The last ant will leave the tunnel in X seconds - NAME1 and NAME2.
 *
 * This matches the classic UVa 10714/10881-style "last ant" identification.
 */
public class Main {
    static class Ant {
        int pos;
        char dir;
        String name;
        Ant(int pos, char dir, String name) {
            this.pos = pos;
            this.dir = dir;
            this.name = name;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int T = Integer.parseInt(first);
        StringBuilder out = new StringBuilder();

        for (int tc = 0; tc < T; tc++) {
            int n = fs.nextInt();
            int L = fs.nextInt();

            Ant[] ants = new Ant[n];
            for (int i = 0; i < n; i++) {
                String d = fs.next();
                int p = fs.nextInt();
                String name = fs.next();
                ants[i] = new Ant(p, Character.toUpperCase(d.charAt(0)), name);
            }

            Arrays.sort(ants, Comparator.comparingInt(a -> a.pos));

            int maxTime = -1;
            boolean leftAtMax = false;
            boolean rightAtMax = false;

            for (Ant a : ants) {
                int t = (a.dir == 'L') ? a.pos : (L - a.pos);
                if (t > maxTime) {
                    maxTime = t;
                    leftAtMax = rightAtMax = false;
                    if (a.dir == 'L') leftAtMax = true;
                    else rightAtMax = true;
                } else if (t == maxTime) {
                    if (a.dir == 'L') leftAtMax = true;
                    else rightAtMax = true;
                }
            }

            int leftIndex = 0;
            int rightIndex = n - 1;
            String leftName = null, rightName = null;

            // Process all exits in chronological order only insofar as needed
            // to know which labels are at the ends when time == maxTime.
            // Ants with smaller exit times consume labels from left/right.
            for (Ant a : ants) {
                int t = (a.dir == 'L') ? a.pos : (L - a.pos);
                if (t < maxTime) {
                    if (a.dir == 'L') leftIndex++;
                    else rightIndex--;
                }
            }

            if (leftAtMax) leftName = ants[leftIndex].name;
            if (rightAtMax) rightName = ants[rightIndex].name;

            out.append("The last ant will leave the tunnel in ")
               .append(maxTime)
               .append(" seconds - ");

            if (leftAtMax && rightAtMax) {
                if (leftName.equals(rightName)) {
                    out.append(leftName);
                } else {
                    out.append(leftName).append(" and ").append(rightName);
                }
            } else if (leftAtMax) {
                out.append(leftName);
            } else {
                out.append(rightName);
            }
            out.append(".\n");
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
